#include "vmx_ept_hook_location.h"
#include <stddef.h>
#define LARGE (UINT64_C(1)<<7)
#define PA UINT64_C(0x0000FFFFFFFFF000)
#define TWO_MB UINT64_C(0x200000)
static int Span(const void*v,size_t n,uintptr_t*b,uintptr_t*e){uintptr_t f=(uintptr_t)v;if(!v||!n||f>UINTPTR_MAX-n)return 0;*b=f;*e=f+n;return 1;}
static int Separate(const void*l,size_t ln,const void*r,size_t rn){uintptr_t lb,le,rb,re;return Span(l,ln,&lb,&le)&&Span(r,rn,&rb,&re)&&(le<=rb||re<=lb);}
static int OutputSeparate(const VMX_EPT_DOMAIN*d,const void*out,size_t n){size_t pages,index;if(!d||!out||d->Binding.VirtualBytes>SIZE_MAX||d->Binding.PageCount>SIZE_MAX/sizeof(*d->Binding.PagesByOrdinal)||d->Binding.PageCount>SIZE_MAX/sizeof(*d->Binding.PhysicalIndex))return 0;pages=(size_t)d->Binding.PageCount*sizeof(*d->Binding.PagesByOrdinal);index=(size_t)d->Binding.PageCount*sizeof(*d->Binding.PhysicalIndex);return Separate(d,sizeof(*d),out,n)&&Separate(d->Binding.VirtualBase,(size_t)d->Binding.VirtualBytes,out,n)&&Separate(d->Binding.PagesByOrdinal,pages,out,n)&&Separate(d->Binding.PhysicalIndex,index,out,n);}
static uint64_t EntryAt(const VMX_EPT_DOMAIN*d,uint32_t ordinal,uint32_t index){const uint64_t*page=(const uint64_t*)((const unsigned char*)d->Binding.VirtualBase+(size_t)ordinal*VMX_EPT_TABLE_PAGE_SIZE);return page[index];}
VMX_EPT_HOOK_LOCATION_STATUS VmxEptHookLocate2Mb(const VMX_EPT_DOMAIN*d,uint64_t gpa,VMX_EPT_HOOK_LOCATION*out){VMX_EPT_HOOK_LOCATION s={0};uint64_t leaf;uint32_t pd_first,pd_page;if(!d||!out||(gpa&(VMX_EPT_HOOK_PAGE_BYTES-1))||VmxEptDomainValidate(d)!=VMX_EPT_DOMAIN_OK||!OutputSeparate(d,out,sizeof(*out)))return VMX_EPT_HOOK_LOCATION_INVALID;if(d->Identity.LeafKind!=VMX_EPT_ENTRY_LEAF_2MB)return VMX_EPT_HOOK_LOCATION_UNSUPPORTED;if(gpa>=d->Identity.MappedBytes)return VMX_EPT_HOOK_LOCATION_NOT_MAPPED;pd_first=1u+d->Plan.PdptPages;pd_page=(uint32_t)(gpa>>30);if(pd_page>=d->Plan.PdPages||pd_first>UINT32_MAX-pd_page||pd_first+pd_page>=d->Binding.PageCount)return VMX_EPT_HOOK_LOCATION_INVALID;s.GuestPhysicalPage=gpa;s.ParentPageOrdinal=pd_first+pd_page;s.ParentEntryIndex=(uint32_t)((gpa>>21)&UINT64_C(0x1ff));s.ObservedParentEntry=EntryAt(d,s.ParentPageOrdinal,s.ParentEntryIndex);s.MutationGeneration=d->MutationGeneration;leaf=gpa&~(TWO_MB-1);if(!(s.ObservedParentEntry&LARGE)||(s.ObservedParentEntry&PA)!=leaf)return VMX_EPT_HOOK_LOCATION_UNSUPPORTED;*out=s;return VMX_EPT_HOOK_LOCATION_OK;}
bool VmxEptHookLocationValid(const VMX_EPT_DOMAIN*d,const VMX_EPT_HOOK_LOCATION*l){VMX_EPT_HOOK_LOCATION expected;if(!d||!l||l->Reserved||!OutputSeparate(d,l,sizeof(*l)))return false;return VmxEptHookLocate2Mb(d,l->GuestPhysicalPage,&expected)==VMX_EPT_HOOK_LOCATION_OK&&expected.GuestPhysicalPage==l->GuestPhysicalPage&&expected.ObservedParentEntry==l->ObservedParentEntry&&expected.MutationGeneration==l->MutationGeneration&&expected.ParentPageOrdinal==l->ParentPageOrdinal&&expected.ParentEntryIndex==l->ParentEntryIndex;}
